        int latShift,
        int lonShift,
        int latBase,
        int lonBase,
        int maxLatDelta,
        int maxLonDelta,
        byte[] relations,
        double lat,
        double lon,
        double distanceKey) {
      super(latShift, lonShift, latBase, lonBase, maxLatDelta, maxLonDelta, relations);
      this.lat = lat;
      this.lon = lon;
      this.distanceKey = distanceKey;
    }

