import org.apache.lucene.geo.*;
public class Probe2 {
  public static void main(String[] args) {
    int base = Integer.MAX_VALUE;
    double pointLat = GeoEncodingUtils.decodeLatitude(base - 2);
    double pointLon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon p = new Polygon(
      new double[] {minLat, minLat, maxLat, maxLat, minLat},
      new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D c = LatLonGeometry.create(p);
    System.out.println("point lat="+pointLat+" lon="+pointLon);
    System.out.println("bounds minX="+c.getMinX()+" maxX="+c.getMaxX()+" minY="+c.getMinY()+" maxY="+c.getMaxY());
    System.out.println("contains="+c.contains(pointLon, pointLat));
    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(c);
    System.out.println("encoded point lat="+(base-2)+" lon="+(base-2));
    System.out.println("predicate="+pred.test(base-2, base-2));
    // scan nearby encoded values
    for (int dlat = -5; dlat <= 5; dlat++) {
      for (int dlon = -5; dlon <= 5; dlon++) {
        int lat = base + dlat;
        int lon = base + dlon;
        boolean t = pred.test(lat, lon);
        if (t) System.out.println("MATCH enc lat="+lat+" lon="+lon+" decLat="+GeoEncodingUtils.decodeLatitude(lat)+" decLon="+GeoEncodingUtils.decodeLongitude(lon));
      }
    }
    System.out.println("relate cell full = "+c.relate(c.getMinX(), c.getMaxX(), c.getMinY(), c.getMaxY()));
  }
}
