import org.apache.lucene.geo.*;
import java.lang.reflect.*;
public class Probe3 {
  static Object get(Object o, String n) throws Exception {
    Class<?> c = o.getClass();
    while (c != null) { try { Field f = c.getDeclaredField(n); f.setAccessible(true); return f.get(o); } catch(NoSuchFieldException e){ c=c.getSuperclass(); } }
    throw new RuntimeException("no "+n);
  }
  public static void main(String[] args) throws Exception {
    int base = Integer.MAX_VALUE;
    double pointLat = GeoEncodingUtils.decodeLatitude(base - 2);
    double pointLon = GeoEncodingUtils.decodeLongitude(base - 2);
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    System.out.println("encode minLat="+GeoEncodingUtils.encodeLatitudeCeil(minLat)+" maxLat="+GeoEncodingUtils.encodeLatitude(maxLat)+" minLon="+GeoEncodingUtils.encodeLongitudeCeil(minLon)+" maxLon="+GeoEncodingUtils.encodeLongitude(maxLon));
    Polygon p = new Polygon(new double[]{minLat,minLat,maxLat,maxLat,minLat},new double[]{minLon,maxLon,maxLon,minLon,minLon});
    Component2D c = LatLonGeometry.create(p);
    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(c);
    int latShift=(int)get(pred,"latShift"), lonShift=(int)get(pred,"lonShift"), latBase=(int)get(pred,"latBase"), lonBase=(int)get(pred,"lonBase"), maxLatDelta=(int)get(pred,"maxLatDelta"), maxLonDelta=(int)get(pred,"maxLonDelta");
    byte[] rel=(byte[])get(pred,"relations");
    System.out.println("latShift="+latShift+" lonShift="+lonShift+" latBase="+latBase+" lonBase="+lonBase+" maxLatDelta="+maxLatDelta+" maxLonDelta="+maxLonDelta+" relLen="+rel.length);
    int lat=base-2, lon=base-2;
    int lat2=((lat-Integer.MIN_VALUE)>>>latShift);
    int lon2=((lon-Integer.MIN_VALUE)>>>lonShift);
    System.out.println("lat2="+lat2+" lon2="+lon2+" lat2-latBase="+(lat2-latBase)+" lon2-lonBase="+(lon2-lonBase));
    if(lat2>=latBase && lat2<latBase+maxLatDelta && lon2-lonBase>=0 && lon2-lonBase<maxLonDelta){
      int relation=rel[(lat2-latBase)*maxLonDelta+(lon2-lonBase)];
      System.out.println("relation="+relation+" (OUTSIDE="+Relation.CELL_OUTSIDE_QUERY.ordinal()+" INSIDE="+Relation.CELL_INSIDE_QUERY.ordinal()+" CROSSES="+Relation.CELL_CROSSES_QUERY.ordinal()+")");
      for(int i=0;i<maxLatDelta;i++)for(int j=0;j<maxLonDelta;j++){
        int bi=((latBase+i)<<latShift)+Integer.MIN_VALUE;
        int bj=((lonBase+j)<<lonShift)+Integer.MIN_VALUE;
        int bix=bi+(1<<latShift)-1;
        int bjx=bj+(1<<lonShift)-1;
        System.out.println("cell["+i+","+j+"] latEnc["+bi+","+bix+"] lonEnc["+bj+","+bjx+"] decLat["+GeoEncodingUtils.decodeLatitude(bi)+","+GeoEncodingUtils.decodeLatitude(bix)+"] decLon["+GeoEncodingUtils.decodeLongitude(bj)+","+GeoEncodingUtils.decodeLongitude(bjx)+"] rel="+rel[i*maxLonDelta+j]+" relate="+c.relate(GeoEncodingUtils.decodeLongitude(bj),GeoEncodingUtils.decodeLongitude(bjx),GeoEncodingUtils.decodeLatitude(bi),GeoEncodingUtils.decodeLatitude(bix)).ordinal());
      }
    }
  }
